(()=>{const rows=[];for(const op of [()=>console.count(),()=>console.count(undefined),()=>console.count('default'),()=>console.count(null),()=>console.countReset(),()=>console.count(),()=>console.countReset('missing'),()=>console.count(Symbol('x')),()=>console.countReset(Symbol('x'))]){try{rows.push({result:typeof op()})}catch(e){rows.push({error:e.name,message:e.message})}}let effects=[];const label={toString(){effects.push('string');return'label'}};console.count(label);console.count(label);console.countReset(label);console.count(label);const count=console.count;count.call(null,'borrowed');count.call({},'borrowed');const frame=document.createElement('iframe');document.body.append(frame);frame.contentWindow.console.count('label');console.count('label');return {rows,effects,countName:console.count.name,countLength:console.count.length,resetLength:console.countReset.length}})()
